package com.agacostays.payment.service.impl;
import com.agacostays.payment.config.PaymentGatewayProperties; import com.agacostays.payment.dto.response.GatewayOrderResponse; import com.agacostays.payment.service.PaymentGatewayService; import com.agacostays.payment.util.PaymentUtil; import org.springframework.stereotype.Service; import java.math.*; import java.nio.charset.StandardCharsets; import java.util.UUID; import java.util.HexFormat; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec;
@Service public class PaymentGatewayServiceImpl implements PaymentGatewayService { private final PaymentGatewayProperties props; public PaymentGatewayServiceImpl(PaymentGatewayProperties p){this.props=p;} public GatewayOrderResponse createOrder(BigDecimal amount,String currency,String receipt){String prefix=props.isMockEnabled()?"mock_order_":"gateway_order_";return new GatewayOrderResponse(prefix+UUID.randomUUID(),amount,currency,props.isMockEnabled()?"MOCK":props.getName());} public boolean verifySignature(String orderId,String paymentId,String signature){return hmac(orderId+"|"+paymentId,props.getSecret()).equals(signature);} public String createRefund(String gatewayPaymentId,BigDecimal amount){return (props.isMockEnabled()?"mock_refund_":"gateway_refund_")+UUID.randomUUID();} private String hmac(String msg,String secret){try{String s=(secret==null||secret.isBlank())?"local-development-secret":secret;Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(s.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(m.doFinal(msg.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} }
